  select 7 as ord, 'core tables present'::text as check_name, '8'::text as expected, (select count(*)::text from (values ('profiles'),('arena_rooms'),('arena_room_messages'),('arena_daily_topics'),('media_objects'),('rate_limit_events'),('arena_room_results'),('arena_room_participants')) as t(tbl) where to_regclass('public.'||t.tbl) is not null)::text as actual
  union all
  select 8 as ord, 'RPC signatures exact'::text as check_name, '0'::text as expected, (select count(*)::text from (values
    ('create_arena_daily_topic', 'text, text, public.hood_id, timestamptz, timestamptz, timestamptz, timestamptz, public.arena_topic_status'),
    ('join_arena_topic', 'text, public.take_stance, public.arena_participant_role'),
