  union all
  select 11 as ord, 'run_maintenance not executable by anon'::text as check_name, 'false'::text as expected, has_function_privilege('anon','public.run_maintenance(integer)','EXECUTE')::text::text as actual
  union all
  select 12 as ord, 'run_maintenance not executable by authenticated'::text as check_name, 'false'::text as expected, has_function_privilege('authenticated','public.run_maintenance(integer)','EXECUTE')::text::text as actual
  union all
  select 13 as ord, 'run_maintenance executable by service_role'::text as check_name, 'true'::text as expected, has_function_privilege('service_role','public.run_maintenance(integer)','EXECUTE')::text::text as actual
