  union all
  select 17 as ord, 'TRIPWIRE no cron job rows'::text as check_name, 'ABSENT'::text as expected, case when to_regclass('cron.job') is null then 'ABSENT' else coalesce((xpath('/row/j/text()', query_to_xml('select string_agg(jobname,' || quote_literal('|') || ') as j from cron.job', false, true, '')))[1]::text,'ABSENT') end::text as actual
  union all
  select 18 as ord, 'realtime.messages RLS still enabled'::text as check_name, 'true'::text as expected, coalesce((select relrowsecurity::text from pg_class where oid=to_regclass('realtime.messages')),'ABSENT')::text as actual
  union all
