  union all
  select 25 as ord, 'Storage upload admission trigger enabled'::text as check_name, '1'::text as expected, (select count(*)::text from pg_trigger where tgrelid='storage.objects'::regclass and tgname='beta_storage_upload_admission' and tgenabled<>'D' and tgfoid='public.guard_beta_storage_upload()'::regprocedure)::text as actual
  union all
  select 26 as ord, 'legacy start_clash API execute grants'::text as check_name, '0'::text as expected, (select count(*)::text from (values ('anon'),('authenticated'),('service_role')) r(role) where has_function_privilege(r.role,'public.start_clash(text,text,public.clash_mode)','EXECUTE'))::text as actual
  union all
  select 27 as ord, 'creator continuation approval API table grants'::text as check_name, '0'::text as expected, (select count(*)::text from (values ('anon'),('authenticated'),('service_role')) r(role) where has_table_privilege(r.role,'public.creator_live_continuation_approvals','SELECT,INSERT,UPDATE,DELETE'))::text as actual
