do $postflight$
declare
  v_fail text;
begin
  select string_agg(c.ord::text || '. ' || c.check_name || '  expected=' || c.expected || '  actual=' || c.actual, E'\n')
    into v_fail
    from (
      select r.ord, r.check_name, r.expected, r.actual,
